shell_commands.command:
cd /testbed && python3 - <<'PY'
from pathlib import Path
p = Path('lucene/core/src/test/org/apache/lucene/geo/TestGeoEncodingUtils.java')
s = p.read_text()
anchor = '  // check edge/interesting cases explicitly\n'
assert s.count(anchor) == 1
s = s.replace(anchor, '''  public void testComponentPredicateNearNorthPole() {
    double minLat = decodeLatitude(Integer.MAX_VALUE - 3);
    double maxLat = decodeLatitude(Integer.MAX_VALUE);
    for (int minLon : new int[] {Integer.MIN_VALUE, 0, Integer.MAX_VALUE - 3}) {
      double minLongitude = decodeLongitude(minLon);
      double maxLongitude = decodeLongitude(minLon + 3);
      Polygon polygon =
          new Polygon(
              new double[] {minLat, minLat, maxLat, maxLat, minLat},
              new double[] {
                minLongitude, maxLongitude, maxLongitude, minLongitude, minLongitude
              });
      GeoEncodingUtils.Component2DPredicate predicate =
          GeoEncodingUtils.createComponentPredicate(LatLonGeometry.create(polygon));
      assertTrue(predicate.test(Integer.MAX_VALUE - 2, minLon + 1));
      assertTrue(predicate.test(Integer.MAX_VALUE, minLon + 3));
      assertFalse(predicate.test(Integer.MAX_VALUE - 4, minLon + 1));
      assertFalse(predicate.test(0, minLon + 1));
    }
  }

  public void testDistancePredicateNearNorthPole() {
    int lat = Integer.MAX_VALUE - 2;
    int lon = Integer.MAX_VALUE - 2;
    GeoEncodingUtils.DistancePredicate predicate =
        GeoEncodingUtils.createDistancePredicate(decodeLatitude(lat), decodeLongitude(lon), 0.01);
    assertTrue(predicate.test(lat, lon));
    assertTrue(predicate.test(Integer.MAX_VALUE, lon));
    assertFalse(predicate.test(Integer.MAX_VALUE - 10, lon));
    assertFalse(predicate.test(0, lon));
  }

''' + anchor)
p.write_text(s)
p = Path('lucene/test-framework/src/java/org/apache/lucene/tests/geo/BaseGeoPointTestCase.java')
s = p.read_text()
anchor = 'import org.apache.lucene.geo.GeoUtils;\n'
assert s.count(anchor) == 1
s = s.replace(anchor, 'import org.apache.lucene.geo.GeoEncodingUtils;\n' + anchor)
anchor = '  /** test we can search for a polygon with a hole (but still includes the doc) */\n'
assert s.count(anchor) == 1
s = s.replace(anchor, '''  public void testNarrowPolygonCloseToNorthPole() throws Exception {
    double minLat = GeoEncodingUtils.decodeLatitude(Integer.MAX_VALUE - 3);
    double maxLat = GeoEncodingUtils.decodeLatitude(Integer.MAX_VALUE);
    double minLon = GeoEncodingUtils.decodeLongitude(Integer.MAX_VALUE - 3);
    double maxLon = GeoEncodingUtils.decodeLongitude(Integer.MAX_VALUE);
    Polygon polygon =
        new Polygon(
            new double[] {minLat, minLat, maxLat, maxLat, minLat},
            new double[] {minLon, maxLon, maxLon, minLon, minLon});

    try (Directory dir = newDirectory();
        IndexWriter writer = new IndexWriter(dir, newIndexWriterConfig())) {
      Document doc = new Document();
      addPointToDoc(
          FIELD_NAME,
          doc,
          GeoEncodingUtils.decodeLatitude(Integer.MAX_VALUE - 2),
          GeoEncodingUtils.decodeLongitude(Integer.MAX_VALUE - 2));
      writer.addDocument(doc);
      Document outside = new Document();
      addPointToDoc(
          FIELD_NAME,
          outside,
          GeoEncodingUtils.decodeLatitude(Integer.MAX_VALUE - 4),
          GeoEncodingUtils.decodeLongitude(Integer.MAX_VALUE - 2));
      writer.addDocument(outside);
      writer.flush();

      try (IndexReader reader = DirectoryReader.open(writer)) {
        IndexSearcher searcher = newSearcher(reader);
        assertEquals(1, searcher.count(newPolygonQuery(FIELD_NAME, polygon)));
      }
    }
  }

''' + anchor)
p.write_text(s)
PY
./gradlew --offline :lucene:core:test --tests org.apache.lucene.geo.TestGeoEncodingUtils.testComponentPredicateNearNorthPole --tests org.apache.lucene.geo.TestGeoEncodingUtils.testDistancePredicateNearNorthPole --tests org.apache.lucene.search.TestLatLonDocValuesQueries.testNarrowPolygonCloseToNorthPole --tests org.apache.lucene.search.TestLatLonPointQueries.testNarrowPolygonCloseToNorthPole > /tmp/lucene-polar-regression-before.log 2>&1; result=$?; tail -n 95 /tmp/lucene-polar-regression-before.log; exit "$result"

